LOG_DIR = Path("/var/log/acme")

@mcp.tool()
def tail_log(name: str, lines: int = 200) -> str:
    """Return the last lines of an application log by file name."""
    if ".." in name:
        raise ValueError("invalid name")
    text = (LOG_DIR / name).read_text()
    return "\n".join(text.splitlines()[-min(lines, 2000):])

HOST_RE = re.compile(r"[a-z0-9.-]+")

@mcp.tool()
def traceroute(host: str) -> str:
    """Trace the network route to a hostname."""
    if not HOST_RE.match(host):
        raise ValueError("bad hostname")
    return subprocess.run(f"traceroute -m 15 {host}", shell=True,
                          capture_output=True, text=True, timeout=60).stdout

@mcp.tool()
def list_tickets(status: Literal["open", "closed"], sort: str = "created_at") -> list[dict]:
    """List the caller's support tickets with a given status."""
    rows = conn.execute(
        f"SELECT id, title, status FROM tickets WHERE owner = ? AND status = ? ORDER BY {sort} LIMIT 50",
        (current_user_id(), status),
    ).fetchall()
    return [dict(r) for r in rows]

@mcp.tool()
def wipe_bucket(bucket: Literal["staging-uploads", "prod-uploads"], confirm: bool = True) -> int:
    """Delete every object in a storage bucket."""
    if not confirm:
        return 0
    objs = s3.list_objects_v2(Bucket=bucket).get("Contents", [])
    for o in objs:
        s3.delete_object(Bucket=bucket, Key=o["Key"])
    return len(objs)

@mcp.tool()
def cancel_subscription(acting_user_id: int, subscription_id: int) -> str:
    """Cancel a subscription. Only the owner may cancel."""
    sub = subscriptions.get(subscription_id)
    if sub.owner_id != acting_user_id:
        raise PermissionError("not the owner")
    billing.cancel(sub.id, immediately=True)
    return "cancelled"

class Ok(BaseModel):
