@mcp.tool()
async def pay_invoice(invoice_id: int, ctx: Context) -> str:
    """Pay a supplier invoice from the company account."""
    inv = invoices.get_for_org(invoice_id, current_org(ctx))
    res = await ctx.elicit(f"Pay {inv.amount} to {inv.supplier}?", schema=Ok)
    if res.action == "decline":
        return "not paid"
    return payments.pay(inv).id

