ROOT = Path(os.environ.get("JOURNAL_DIR", Path.home())).resolve()

@mcp.tool()
def read_entry(relative_path: str) -> str:
    """Read a journal entry."""
    p = (ROOT / relative_path).resolve()
    if not p.is_relative_to(ROOT):
        raise ValueError("outside journal")
    return p.read_text()[:50_000]

