REF_OK = re.compile(r"[A-Za-z0-9._/-]{1,100}")

@mcp.tool()
def branch_history(branch: str) -> str:
    """Show the last 20 commits on a branch of the project repo."""
    if not REF_OK.fullmatch(branch) or branch.startswith("-") or ".." in branch:
        raise ValueError("invalid branch name")
    out = subprocess.run(["git", "log", "--oneline", "-n", "20", branch, "--"],
                         cwd=REPO_DIR, capture_output=True, text=True, timeout=15)
    return out.stdout

